import type { ReactElement } from "react";
import "./ProblemTable.css";

export interface ProblemRow {
  readonly title: string;
  readonly pattern: string;
  readonly minutes: number;
  readonly review: string;
  readonly due: boolean;
}

export interface ProblemTableProps {
  readonly rows: readonly ProblemRow[];
  readonly caption?: string;
}

export function ProblemTable({
  rows,
  caption = "Solved problems",
}: ProblemTableProps): ReactElement {
  return (
    <div className="problem-table__scroll">
      <table className="problem-table">
        <caption className="problem-table__caption">{caption}</caption>
        <thead>
          <tr>
            <th scope="col">Title</th>
            <th scope="col">Pattern</th>
            <th scope="col" className="problem-table__num">Minutes</th>
            <th scope="col">Next review</th>
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 ? (
            <tr>
              <td className="problem-table__empty" colSpan={4}>
                No solved problems yet.
              </td>
            </tr>
          ) : (
            rows.map((row, index) => (
              <tr key={`${index}-${row.title}`} tabIndex={0} className="problem-table__row">
                <th scope="row" className="problem-table__title">
                  {row.title}
                </th>
                <td>{row.pattern}</td>
                <td className="problem-table__num">{row.minutes}</td>
                <td
                  className={
                    row.due
                      ? "problem-table__review problem-table__review--due"
                      : "problem-table__review"
                  }
                >
                  {row.review}
                  {row.due ? <span className="problem-table__sr-only"> (due today)</span> : null}
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
}
