  outline-offset: -2px;
}

.problem-table__review {
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.problem-table__review--due {
  background: var(--pt-due-bg);
  color: var(--pt-due-text);
  font-weight: 600;
}

.problem-table__empty {
  color: var(--pt-muted);
  font-style: italic;
  text-align: center;
  padding: 1rem 0.75rem;
}

.problem-table__sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
